<script setup>
import {onMounted,ref,computed} from 'vue'
import {Search,Download,ClipboardCheck,ArrowDownUp} from 'lucide-vue-next'
import {rpc,data} from '../transport'
import {notice} from '../state'
const rows=ref([]),search=ref(''),filter=ref('all'),selected=ref([])
const visible=computed(()=>rows.value.filter(r=>(filter.value==='all'||r.state===filter.value)&&r.title.toLowerCase().includes(search.value.toLowerCase())))
onMounted(async()=>{try{rows.value=(await rpc('protocols.list')).rows||[]}catch(e){notice(e.message)}})
function exportCsv(){const list=selected.value.length?visible.value.filter(r=>selected.value.includes(r.id)):visible.value;const blob=new Blob(['\ufeffBauteil;Zeit;Druck;Druckabfall;Ergebnis\n'+list.map(r=>[r.title,r.created,data(r).pressure,data(r).drop,r.state].join(';')).join('\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pruefprotokolle.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><div><div class="compact-intro"><div><div class="eyebrow">QUALITÄTSSICHERUNG</div><h1>Prüfprotokolle</h1><p>Ergebnisse des simulierten Ventilprüfstands.</p></div><button class="button outline" :disabled="!rows.length" @click="exportCsv"><Download :size="16"/> CSV exportieren</button></div><div class="stats-row"><div><span>Prüfungen</span><strong>{{rows.length}}</strong></div><div><span>Bestanden</span><strong>{{rows.filter(r=>r.state==='passed').length}}</strong></div><div><span>Nacharbeit</span><strong>{{rows.filter(r=>r.state==='failed').length}}</strong></div></div><div class="panel table-panel"><div class="table-toolbar"><h2>Prüfprotokolle</h2><div class="table-filters"><label class="search-field"><Search :size="17"/><input v-model="search" placeholder="Bauteil suchen" aria-label="Bauteil suchen"></label><select v-model="filter" aria-label="Ergebnis filtern"><option value="all">Alle Ergebnisse</option><option value="passed">Bestanden</option><option value="failed">Nacharbeit</option></select></div></div><div class="table-scroll"><table><thead><tr><th></th><th>Bauteil</th><th>Prüfstand</th><th>Druck</th><th>Druckabfall</th><th>Ergebnis</th><th>Zeitpunkt</th></tr></thead><tbody><tr v-for="r in visible" :key="r.id"><td><input v-model="selected" :value="r.id" type="checkbox" :aria-label="r.title+' auswählen'"></td><td><strong>{{r.title}}</strong><small>Kühlmittelventil KV-24</small></td><td>VP-01</td><td>{{data(r).pressure?.toFixed(2)}} bar</td><td>{{data(r).drop?.toFixed(3)}} bar</td><td><span class="tag" :class="r.state==='passed'?'success':'warning'">{{r.state==='passed'?'Bestanden':'Nacharbeit'}}</span></td><td>{{r.created}}</td></tr></tbody></table></div><div v-if="!visible.length" class="empty-state"><ClipboardCheck :size="34"/><h3>{{rows.length?'Keine passenden Ergebnisse.':'Keine Prüfprotokolle vorhanden.'}}</h3><p>Starte einen Prüfzyklus am Ventilprüfstand. Das Ergebnis erscheint anschließend hier.</p><RouterLink class="button secondary" to="/machines/valve-leak-test">Zum Prüfstand</RouterLink></div><div class="table-footer">{{visible.length}} Ergebnisse <span v-if="selected.length">{{selected.length}} ausgewählt</span></div></div></div></template>
